// Generated by forge. New npm dependencies exist on the registry (run by .forge/check.sh with
// bun). Usage: bun new_deps.mjs <forge-tmp> <cooldown-seconds>
// For each changed package.json, the names its dependencies, devDependencies,
// optionalDependencies and peerDependencies gain over the base copy, with a registry spec (a
// version range, a tag, npm:<name>@<range>; not workspace:, file:, link:, git or URL specs), are
// looked up on registry.npmjs.org: a name that does not exist, a deprecated version (the newest
// one the range allows), and a package first published less than <cooldown> ago are findings
// ("path:line message", at the dependency's line). A name whose scope .npmrc maps to another
// registry (@scope:registry=), or every name when .npmrc sets another default registry, is the
// private registry's and is not looked up. The registry unreachable: exit 3, "skipped: …".
// FORGE_REGISTRY_NPM replaces https://registry.npmjs.org (a mirror; the tests).
// Exit 0: nothing found; 1: findings printed; 3: cannot run.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";

const [tmp, cooldownArg] = process.argv.slice(2);
const cooldown = Number(cooldownArg) || 0;
const REGISTRY = (process.env.FORGE_REGISTRY_NPM || "https://registry.npmjs.org").replace(/\/$/, "");
const lines = (name) => { try { return readFileSync(join(tmp, name), "utf8").split("\n").filter(Boolean); } catch { return []; } };
const read = (p) => { try { return readFileSync(p, "utf8"); } catch { return null; } };
const json = (t) => { try { return JSON.parse(t); } catch { return null; } };
const SECTIONS = ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"];

function deps(text) {
  const out = new Map();
  const pkg = text === null ? null : json(text);
  for (const s of SECTIONS) for (const [k, v] of Object.entries(pkg?.[s] ?? {})) if (typeof v === "string" && !out.has(k)) out.set(k, v);
  return out;
}

/** The registry name and range of a spec, or null when it is not a registry spec. */
function registrySpec(name, spec) {
  const s = spec.trim();
  if (/^npm:/.test(s)) {
    const m = /^npm:((?:@[^/@]+\/)?[^@]+)(?:@(.*))?$/.exec(s);
    return m ? { name: m[1], range: m[2] || "*" } : null;
  }
  if (/^(workspace|file|link|portal|patch|catalog|git|git\+[a-z]+|github|gitlab|bitbucket|https?):/.test(s) || /^[^@\s]+\/[^\s]+$/.test(s) || s.startsWith(".") || s.startsWith("/")) return null;
  return { name, range: s || "*" };
}

/** .npmrc registry settings (the manifest's directory, then the root): default and per scope. */
function registries(dir) {
  const out = { default: null, scopes: new Map() };
  for (const f of [join(dir, ".npmrc"), ".npmrc"]) {
    const t = read(f);
    if (t === null) continue;
    for (const raw of t.split(/\r?\n/)) {
      const l = raw.replace(/[#;].*$/, "").trim();
      const m = /^(@[^:\s]+):registry\s*=\s*(\S+)/.exec(l);
      if (m && !out.scopes.has(m[1])) out.scopes.set(m[1], m[2]);
      const d = /^registry\s*=\s*(\S+)/.exec(l);
      if (d && out.default === null) out.default = d[1];
    }
  }
  return out;
}
const isNpmjs = (url) => /^https?:\/\/registry\.npmjs\.(org|com)\/?$/.test(url) || /^https?:\/\/registry\.yarnpkg\.com\/?$/.test(url);

function newest(versions, range) {
  const ok = versions.filter((v) => !v.includes("-") && Bun.semver.satisfies(v, range));
  const pool = ok.length ? ok : versions.filter((v) => Bun.semver.satisfies(v, range));
  return pool.sort((a, b) => Bun.semver.order(a, b)).pop();
}

async function lookup(name) {
  const url = `${REGISTRY}/${name.replace("/", "%2f")}`;
  let r;
  try {
    r = await fetch(url, { signal: AbortSignal.timeout(20000), headers: { accept: "application/json" } });
  } catch (e) {
    return { unreachable: String(e?.message ?? e) };
  }
  if (r.status === 404) return { missing: true };
  if (!r.ok) return { unreachable: `${url} answered ${r.status}` };
  const doc = await r.json().catch(() => null);
  return doc ? { doc } : { unreachable: `${url} answered something that is not JSON` };
}

const found = [];
let unreachable = "";
for (const file of lines("changed")) {
  if (!/(^|\/)package\.json$/.test(file) || /(^|\/)node_modules\//.test(file) || !existsSync(file)) continue;
  const text = read(file);
  const now = deps(text);
  const then = deps(read(join(tmp, "base", file)));
  const regs = registries(dirname(file));
  const fileLines = (text ?? "").split("\n");
  for (const [key, spec] of now) {
    if (then.has(key)) continue;
    const want = registrySpec(key, spec);
    if (!want) continue;
    const scope = want.name.startsWith("@") ? want.name.split("/")[0] : null;
    const reg = (scope && regs.scopes.get(scope)) || regs.default;
    if (reg && !isNpmjs(reg)) continue;
    const at = Math.max(0, fileLines.findIndex((l) => l.includes(`"${key}"`)) + 1);
    const res = await lookup(want.name);
    if (res.unreachable) { unreachable = res.unreachable; continue; }
    if (res.missing) { found.push(`${file}:${at} ${want.name} does not exist on the npm registry; check the name (a hallucinated or typo-squatted package?)`); continue; }
    const doc = res.doc;
    const versions = Object.keys(doc.versions ?? {});
    const tag = doc["dist-tags"]?.[want.range];
    const v = tag ?? newest(versions, want.range);
    const dep = v ? doc.versions?.[v]?.deprecated : undefined;
    if (typeof dep === "string" && dep) found.push(`${file}:${at} ${want.name}@${v} is deprecated: ${dep.replace(/\s+/g, " ").trim()}`);
    if (v === undefined && versions.length) found.push(`${file}:${at} ${want.name}: no published version matches ${want.range}`);
    const created = Date.parse(doc.time?.created ?? "");
    if (cooldown && Number.isFinite(created) && Date.now() - created < cooldown * 1000)
      found.push(`${file}:${at} ${want.name} was first published ${new Date(created).toISOString().slice(0, 10)}, less than ${Math.round(cooldown / 86400)} days ago; a new package needs the user's review before it is used`);
  }
}
for (const f of found) console.log(f);
if (found.length) process.exit(1);
if (unreachable) { console.log(`skipped: registry unreachable (${unreachable})`); process.exit(3); }
process.exit(0);
